// @ts-check
// French localization overlay for character data — data/characters.js.
// Keyed by the exact same names as CHARACTER_DATA. Same policy as the other
// *.fr.js overlays: element names, echo/weapon/set/monster proper nouns kept
// untranslated; combat terminology kept consistent with the rest of the app
// (Compétence de Résonance, Libération de Résonance, Attaque Basique/Lourde,
// Outro/Intro, DGT, ATQ, Taux Critique, Dégâts Critiques, Bouclier...).
// "Rover" is officially "Nomade" in French (confirmed via the French
// the reference) -- used here in all flavor text. NOTE: the character's
// in-app *name* (used as the CHARACTER_DATA key, card titles, ownership
// tracking, etc.) is NOT renamed here -- that would require restructuring
// how the app keys/display characters and is out of scope for this pass;
// this overlay only translates the `desc` bio/kit-summary text.
//
// IMPORTANT: `desc` here is DISPLAY TEXT ONLY. CharacterDetailModal.jsx
// splits it on the first ". " to separate lore from gameplay summary --
// purely textual, no functional/regex parsing depends on English keywords
// here (verified before writing this file), unlike echoes.js/weapons.js.

/** @type {Record<string, string>} */
export const CHARACTER_DESC_FR = {
  'Rover: Spectro': "Un vagabond qui s'est réveillé sans mémoire sur les rives de Solaris. Attunement Spectro : une debuffeuse de Lumière Spectro à changement rapide — la Rotation Résonnante du Circuit Forte applique Lumière Spectro (avec Chatoiement pour stopper sa dégradation) et la Libération Orchestre en Écho en ajoute davantage, puis change de personnage pour laisser place au DPS principal.",
  'Rover: Havoc': "Un vagabond qui s'est réveillé sans mémoire sur les rives de Solaris. Attunement Havoc : un DPS principal sur le terrain — maintenez l'Attaque Lourde à Umbra plein pour lancer Dévastation et entrer en Poussée Sombre, un combo à état amélioré qui se termine par le nuke de Libération à 1520 % ATQ, Abysse qui S'éteint.",
  'Rover: Aero': "Un vagabond qui s'est réveillé sans mémoire sur les rives de Solaris. Attunement Aero : un soigneur/soutien dont Rupture Céleste retire les cumuls de Lumière Spectro, Ravage Havoc, Explosion Fusion, Givre Glaçant et Électromagnétisme d'une cible et convertit chacun en un cumul d'Érosion Aéronautique, tandis que le Forte et la Libération soignent tous deux l'équipe.",
  'Rover: Electro': "Un vagabond qui s'est réveillé sans mémoire sur les rives de Solaris. Attunement Electro : un hybride en Posture de Parade — maintenez l'Attaque Basique pour l'immunité aux interruptions et une réduction de 60 % des DGT, puis dépensez la Poussée Électrique en un buff d'ATQ d'équipe ou en Résonance Apex, débloquant le combo multi-élémentaire Thrum of All Sounds du Forte. Actuellement l'attunement le plus faible, faute d'un partenaire DPS solide.",
  'Jiyan': "Cavalier du Vent, chef des Rôdeurs de Minuit de Jinzhou, agit avec une droiture prompte et résolue — il possède la formidable capacité d'invoquer un puissant Qingloong à partir des vents, le rendant invincible sur le champ de bataille. DPS Aero sur le terrain qui accumule de la Résolution via l'Attaque Normale et la Compétence d'Intro Frappe Tactique, la dépensant sur un Dompteur des Vents renforcé ou le nuke Emerald Storm : Finale, puis déchaîne Emerald Storm : Prélude pour entrer en Mode Qingloong — un combo Lance de Qingloong percutant à haute résistance à l'interruption.",
  'Calcharo': "Chasseur Fantôme, chef du groupe mercenaire international des « Chiens Fantômes » — impitoyable, vengeur, implacable ; un client potentiel doit être conscient du prix à payer avant de lui faire une offre. DPS Electro sur le terrain qui accumule de la Cruauté via sa Compétence de Résonance Ordre d'Extermination en une Attaque Lourde renforcée « Pitié », puis déclenche la Libération de Résonance Gravure Fantôme pour entrer en Équipement de Lame de Mort, remplaçant son Attaque Normale par le finisseur en rafale « Messager de la Mort » alimenté par l'Intention Meurtrière.",
  'Encore': "Jeu du Comptage des Moutons, une fille des Rives Noires accompagnée d'un Wooly noir et d'un Wooly blanc, qui rêve de créer des histoires heureuses avec des bonbons, des contes de fées et son imagination. DPS Fusion sur le terrain qui accumule du Chaos via ses coups Basique/Compétence/Intro en une Attaque Lourde renforcée et réductrice de dégâts (Frénésie Nuageuse), puis déchaîne la Libération de Résonance Rave Cosmique pour transformer tout son kit en versions Fusion améliorées pendant 10 s.",
  'Jianxin': "Lance Étoilée Guide, moniale taoïste et héritière du Fengyiquan qui a dédié sa vie à maîtriser l'art martial ultime — avec le pouvoir de canaliser et transformer le Chi environnant, elle crée des barrières protectrices qui purifient à la fois le corps et l'esprit. Soutien/sous-DPS à Bouclier qui canalise l'Attaque Lourde Spirale de Chi Primordial (Progrès du Zhoutian) pour un vaste bouclier proportionnel aux PV et des soins périodiques d'équipe, regroupe les ennemis avec le Champ de Force de Purification de la Libération, et confère au personnage entrant +38 % DGT de Libération de Résonance via son Outro.",
  'Lingyang': "Bourrasque Givrée, membre enthousiaste et courageux de la Troupe de la Danse du Lion de Jinzhou et dernier Suan'ni vivant — un visiteur sincère et compatissant de la communauté humaine doté de capacités physiques incroyables, qui incarne l'esprit de la Danse du Lion avec son style unique. DPS Glacio sur le terrain qui accumule l'Esprit du Lion via sa Compétence de Résonance Poings Furieux, puis le déchaîne via l'Attaque Lourde Plongeon Glorieux pour entrer dans l'état aérien du Lion Bondissant, enchaînant des Attaques Normales améliorées, Vagabond des Montagnes et Coups de Pied Tempétueux.",
  'Verina': "L'Appel de la Nature — dotée d'une vaste connaissance de la botanique, Verina est toujours prévenante, toujours souriante, et souhaite toujours que chaque fleur soit bénie du miracle de la vie. Soigneuse Spectro qui accumule de l'Énergie de Photosynthèse via l'Attaque Normale, la Compétence et l'Intro, puis la dépense en Attaques Lourdes/Aériennes Éclosions de Fleurs Stellaires pour soigner l'équipe ; la Libération Floraison Arboricole soigne et marque les ennemis pour un soin sur Attaque Coordonnée, tandis que l'Outro Éclosion soigne le personnage entrant et confère à l'équipe une Amplification de tous les DGT.",
  'Yinlin': "Marionnette Exécutrice — une Patrouilleuse habile et une puissante Résonatrice Naturelle de Jinzhou ; après avoir été suspendue de ses fonctions au Bureau de la Sécurité Publique, elle doit désormais traquer les maux cachés dans le secret. Sous-DPS Electro qui marque les cibles du Sceau du Pécheur via l'Attaque Normale et la Compétence d'Intro, inflige des DGT Electro hors du terrain via des Attaques Coordonnées (Salve Électromagnétique/Frappe du Jugement) une fois la Marque du Châtiment appliquée, et amplifie les DGT Electro et les DGT de Libération de Résonance du coéquipier entrant via son Outro.",
  'Jinhsi': "Renouveau de l'Aube, Magistrate de Jinzhou, illumine doucement les espoirs de son peuple comme des rayons de soleil hivernal — en tant que Résonatrice Désignée du Sentinel vénéré, elle fait preuve d'humilité et se consacre corps et âme à guider son peuple vers un avenir radieux. DPS Spectro sur le terrain qui accumule de l'Incandescence à partir des DGT d'Attribut ou Coordonnés de n'importe quel membre de l'équipe, entre en Incarnation via sa Compétence de Résonance, puis dépense ses cumuls via Épiphanie Lumineuse pour un nuke Éclat Stella évolutif.",
  'Changli': "Flamme Éternelle, conseillère au service de la Magistrate de Jinzhou et ancienne Secrétaire Générale dans la capitale — enveloppée de flammes, elle est destinée à brûler intensément jusqu'à ses dernières braises, s'élevant au pouvoir avec une détermination ardente et un esprit toujours stratégique. DPS Fusion sur le terrain qui entre en Vraie Vision depuis les finisseurs de son Attaque Normale/Compétence/Intro, accumule des cumuls d'Enflammement à partir des suivis de Vraie Vision, puis déchaîne l'Attaque Lourde renforcée Sacrifice Ardent — un kit rapide et propice au changement rapide qui confère aussi au personnage entrant un buff de DGT Fusion et de Libération via son Outro.",
  'Zhezhi': "Pinceau Enchanté — peintre timide et discrète de la scène artistique de Jinzhou dont les créations à l'encre prennent vie et combattent à son commandement ; sa timidité masque une dévotion farouche envers son art et ceux qu'elle appelle amis. Sous-DPS/soutien Glacio qui peint des Empreintes Fantasmagoriques durant son Attaque Normale et son combo Forte, les consomme pour déchaîner des nukes Glacio hors du terrain en Attaque Coordonnée via sa Libération de Résonance (Toile Vivante), et confère au personnage entrant un buff de DGT Glacio et DGT de Compétence via son Outro Sculpture et Dessin.",
  'Xiangli Yao': "Tisseur de Matière, Enquêteur Principal à l'Académie Huaxu de Jinzhou et son plus jeune scientifique multidisciplinaire — une âme douce à l'esprit vif dont la passion inlassable pour la Mécanique des Automates se traduit toujours en découvertes constructives. DPS principal Electro sur le terrain qui accumule de la Capacité via ses combos Attaque Normale/Compétence, entre en Intuition via sa Libération de Résonance (Modèle de Cogitation) pour gagner 3 Hypercubes et des attaques renforcées, puis consume chaque Hypercube via la Compétence renforcée Loi des Règnes pour ses dégâts explosifs principaux — son Outro Règle de Chaîne déclenche ensuite des tirs laser bonus sur les Attaques Normales du personnage entrant.",
  'Shorekeeper': "Chrysalide Euphonique, gardienne des Rives Noires — ce titre seul la définissait autrefois, mais désirs, liens et émotions, elle n'a commencé à les comprendre qu'après vous avoir rencontré. Soutien/soigneuse Spectro qui restaure les PV en continu via sa Compétence de Résonance (Théorie du Chaos) et sa Libération, ouvre le champ Stellarealm via sa Libération de Résonance (Boucle de Fin) qui évolue pour conférer Taux Critique puis Dégâts Critiques à toute l'équipe (proportionnel à sa propre Régén. d'Énergie) lorsque les alliés lancent leurs Compétences d'Intro à l'intérieur, et confère à toute l'équipe un buff de tous les DGT via son Outro Papillon Binaire.",
  'Camellya': "Fleur Sanguine, Porteuse de Floraison des Rives Noires — libre d'esprit et dangereusement charmante, elle parcourt Solaris à la recherche de talents, s'immergeant dans le présent et savourant ses plaisirs, sans être encombrée de pensées sur le passé ou le futur. DPS principal Havoc sur le terrain qui alterne entre Cheveux Blancs (mobile) et Cheveux Rouges/Mode Floraison (rotation stationnaire en zone) via sa Compétence, accumule des Pistils Cramoisis en Bourgeons Cramoisis, déchaîne l'explosion du Forte Éphémère en Mode Bourgeonnant pour une équipe d'Attaques Basiques amplifiées, et conclut avec le nuke Entrelacement de son Outro.",
  'Carlotta': "Remodeler les Dimensions, seconde fille de la famille Montelli et investisseuse d'art non conventionnelle — elle évolue sans effort à travers les cercles sociaux et les transactions commerciales tout en gérant discrètement les « ennuis » inavouables de la famille. DPS principal Glacio sur le terrain qui accumule Cristaux Modelables et Substance via ses combos Attaque Normale/Lourde et Compétence, déchaîne l'Attaque Lourde du Forte Oblivion Imminente à Substance maximale pour Révérence Finale, puis déverse sa Libération de Résonance entièrement rechargée Ère de la Nouvelle Vague dans un barrage à six coups Tango du Crépuscule (Glas de Mort ×4 en Finale Fatale) pour une explosion massive de DGT marqués Compétence de Résonance.",
  'Roccia': "Scène dans la Boîte, assistante, accessoiriste et comédienne d'improvisation de la Troupe des Fous — toujours présente pour s'assurer que la Troupe est prête, portant une Boîte Magique qui semble contenir le monde, ou peut-être un monde qu'elle a recréé à l'intérieur. Sous-DPS/buffeuse Havoc qui attire les ennemis et entre en Au-delà de l'Imagination via sa Compétence, rebondit à travers 3 coups Réelle Fantaisie du Forte (comptés comme DGT d'Attaque Lourde), inflige un nuke avec sa Libération pour un buff d'ATQ d'équipe plat proportionnel à son propre Taux Critique, puis confère au personnage entrant un buff de DGT Havoc et d'Attaque Basique via son Outro Applaudissements, s'il vous plaît ! — le meilleur utilitaire de regroupement d'ennemis du jeu via sa Compétence et sa Boîte Magique transférable.",
  'Phoebe': "Luminescence Gracieuse, Acolyte de l'Ordre des Profondeurs — une jeune femme d'une dévotion silencieuse qui accomplit ses devoirs avec une diligence inébranlable, ses prières offrant réconfort et paix comme la lumière qu'elle porte. Hybride Spectro à double mode qui consomme la Prière à Forte plein pour entrer soit en Absolution (DPS principal auto-buffé, amplifiant sa propre Attaque Lourde Éclat Stellaire contre le Lumière Spectro) soit en Confession (mode soutien, empilant du Lumière Spectro sur les ennemis et conférant à l'allié sur le terrain un buff de DGT de Lumière Spectro via l'Outro) — Phoebe en Confession est spécifiquement bâtie pour renforcer Zani, son seul partenaire DPS-Lumière Spectro actuel.",
  'Brant': "Boussole Enflammée, capitaine de la Troupe des Fous de Rinascita — un esprit libre et romantique, imprévisible et plein de vie, le cœur battant de la troupe qui se glisse dans d'innombrables rôles sur scène mais reste inébranlablement sincère en dehors. DPS principal/hybride Fusion qui remplit son Bravo du Forte via des enchaînements d'Attaque Basique aérienne et son Intro, déchaîne la Compétence explosive du Forte Revenu des Cendres pour des dégâts massifs plus un bouclier d'équipe, soigne l'équipe à mesure que le Bravo se remplit, et confère au personnage entrant un buff de DGT Fusion et de Compétence de Résonance via son Outro La Voie est Tracée ! — la quasi-totalité de son kit s'exécute en l'air, esquivant gratuitement la plupart des attaques ennemies.",
  'Cantarella': "Mer des Rêves, actuelle chef de la Famille Fisalia, Cantarella le Fléau — une noble mystérieuse dont la beauté est aussi captivante que périlleuse, résidant dans un château en forme de couronne où des rêves illusoires coulent comme des ruisseaux, méticuleusement tissés de ses propres mains. Hybride Havoc qui accumule de la Transe via son Intro/Compétence/Libération, entre en Mirage via l'Attaque Lourde du Forte Plongée Illusoire pour débloquer des Attaques Basiques améliorées et le nuke explosif Drain de Perception, inflige des DGT Havoc hors du terrain via l'Attaque Coordonnée Tisseuses de Rêves de sa Libération, soigne l'équipe tout du long, et confère au personnage entrant un buff de DGT Havoc et de Compétence de Résonance via son Outro Tentacules Douces.",
  'Zani': "Éclat Calciné, membre de l'équipe de sécurité du Caveau d'Averardo et sa « Meilleure Employée » de longue date — elle a plein de projets pour son temps libre, mais pour l'instant sa plus grande mission est simple : pointer sa sortie à l'heure. DPS principal Spectro sur le terrain qui convertit le Lumière Spectro des coéquipières en sa propre Braise Héliaque et Blaze dès qu'il se pose, accumule de l'Énergie Résiduelle via l'Attaque Normale et les parades pour débloquer sa Compétence renforcée, puis déverse tout en Mode Enfer via sa Libération pour une série de combos massifs de Frappes Lourdes marqués à la fois DGT d'Attaque Lourde et DGT de Lumière Spectro — entièrement dépendante d'une coéquipière appliquant le Lumière Spectro qu'elle convertit.",
  'Ciaccona': "Mélodies Tissées, barde errante de Rinascita — elle chante non seulement pour la Divinité, mais aussi pour le peuple, consignant des histoires au fil de ses voyages et les transformant en chansons qui évoquent rire, émotion et larmes chez les conteurs comme chez le public. Hybride Aero qui enchaîne des annulations rapides Attaque Basique/aérienne pour invoquer des clones Sylphe d'Ensemble quasi permanents (Concert Solo : amplification des DGT Aero d'équipe), tire l'Attaque Lourde du Forte Contretemps Quadruple, puis entre dans un état de Récital prolongé via sa Libération pour appliquer des vagues répétées d'Érosion Aéronautique ou de Lumière Spectro même hors du terrain — confère au personnage entrant un buff de DGT d'Érosion Aéronautique via son Outro.",
  'Cartethyia': "Tempête à Plumes, chevalière errante qui parcourt Rinascita — anciennement connue sous le nom de Vierge Bénie, vaisseau de la Divinité, et Reine de la Bourrasque et de la Marée sous le nom de Fleurdelys, elle est désormais simplement libre et sans entraves. DPS principal Aero sur le terrain à scaling PV qui accumule des Ombres de Lame via les finisseurs de son Attaque Basique/Compétence/Intro, les rappelle via l'Attaque Aérienne, se transforme en Fleurdelys via sa Libération pour un kit entièrement renforcé, bâtit de la Conviction vers la dévastatrice seconde Ultimate Lame de la Bourrasque Hurlante qui consume l'Érosion Aéronautique accumulée pour des DGT bonus, puis confère au personnage entrant un buff de DGT Aero contre les cibles en État Négatif via son Outro.",
  'Lupa': "Flamme Hurlante, Gladiatrice de Septimont et étoile radieuse de l'arène — ardente et directe, Lupa vit comme une louve solitaire sauvage, et tant qu'elle peut savourer la montée d'adrénaline du combat, elle ne s'inquiète pas si ce même feu finit par la consumer tout entière. Hybride/buffeuse Fusion qui déverse immédiatement sa Libération Gloire Baisée par le Feu pour conférer à toute l'équipe Chasse en Meute (Amplification d'ATQ, encore renforcée par les Compétences d'Intro des coéquipiers) et Gloire (ignorance de RÉS Fusion proportionnelle au nombre de coéquipiers Fusion), accumule de la Foi du Loup via les Attaques Lourdes/Aériennes vers son finisseur du Forte Danse avec la Louve, puis confère au personnage entrant un buff de DGT Fusion et d'Attaque Normale via son Outro — conçue pour renforcer les équipes mono-Fusion comme Changli + Brant + Lupa.",
  'Phrolova': "Symphonie de l'Au-delà, Superviseure des Fractsidus marchant sur la ligne fine entre vie et mort — une chef d'orchestre inquiétante et mortelle dont le silencieux mouvement de baguette suffit à accorder les fréquences mêmes de l'être et à diriger les symphonies des « âmes », sa musique pouvant sculpter un monde meilleur ou tout aussi facilement invoquer une légion pour semer le chaos. DPS principal Havoc qui accumule des Notes Volatiles via des combos Attaque Normale/Compétence et leurs suivis renforcés par le Forte, déchaîne sa Libération pour entrer en état de Maestro et commander sa partenaire Hecate pour des DGT Havoc soutenus hors du terrain (déclenchés davantage par les lancers de Compétence d'Écho de n'importe quel coéquipier), puis confère au personnage entrant un buff de DGT Havoc et d'Attaque Lourde via son Outro.",
  'Augusta': "Éphore de Septimont, un soleil se levant embrasé du creuset de sang et de sable. DPS Electro sur le terrain qui inflige des DGT explosifs d'Attaque Lourde et de Libération avec des boucliers intégrés et un mécanisme d'arrêt du temps sur sa Compétence de Résonance.",
  'Iuno': "Prêtresse du Temple du Tétragone de Septimont qui saisit le sens dans le rythme du temps. Sous-DPS Aero qui confère un buff de DGT d'Attaque Lourde via l'Outro, soigne l'équipe à travers ses attaques Nouvelle Lune et son Domaine Pleine Lune, et se protège d'un bouclier lors des lancers de compétence, alternant entre les états de combat Demi-Lune et Nouvelle Lune.",
  'Galbrena': "Consultante des Rives Noires connue sous le nom de Tueuse de Discorde, arrachant le pouvoir à l'obscurité. DPS Fusion sur le terrain qui inflige des dégâts principaux via des combos de Compétence d'Écho et d'Attaque Lourde en rotations explosives rapides.",
  'Qiuyuan': "Ancien agent de renseignement de Mingting, droit comme le bambou, sans quête de vanité. Sous-DPS/buffeur Aero qui confère au prochain personnage un buff de DGT de Compétence d'Écho via l'Outro et augmente les Dégâts Critiques du personnage actif via la Libération de Résonance.",
  'Chisa': "« Juste une étudiante ordinaire », se présente-t-elle calmement, un léger éclat irisé scintillant dans ses yeux. Soutien/soigneuse Havoc qui inflige de lourds DGT de Libération de Résonance, soigne et protège l'équipe d'un bouclier, et réduit la DÉF ennemie via Piège Invisible + Ravage Havoc.",
  'Lynae': "Une élève de l'Académie Startorch au style électrique qui attire les regards, cachant une concentration intérieure aussi explosive qu'un ressort comprimé. Sous-DPS Spectro qui amplifie tous les DGT d'équipe et les DGT de Libération de Résonance via l'Outro, et augmente le Regain de Rupture Tacet pour les compositions d'équipe Tension Tacet.",
  'Mornye': "Une ingénieure de l'Institut de Recherche du Collectif Trek-spatial et professeure du Département d'Ingénierie Exostrider à l'Académie Startorch. Soigneuse Fusion à scaling DÉF qui restaure les PV via sa Compétence de Résonance et sa Libération tout en augmentant le Taux d'Accumulation Hors-Tonalité de l'équipe.",
  'Luuk Herssen': "Le médecin traitant de l'Unité de Soins des Résonateurs de l'Académie Startorch, réputé pour son intellect vif et son sang-froid inébranlable. DPS d'Attaque Basique Spectro sur le terrain qui alterne les trois formes améliorées de l'Auréole d'Exécution et inflige des DGT Totaux bonus en réagissant à Tension de Tonalité - Brouillé.",
  'Aemeath': "Autrefois Synchroniste Exostrider du Collège Rabelle, elle est désormais un fantôme numérique qui chante doucement parmi les étoiles. DPS Fusion sur le terrain qui bascule entre les Modes de Résonance Rupture de Tonalité et Explosion Fusion, infligeant des DGT de Libération de Résonance massifs via Duo Séraphique et Édit de la Chute Céleste.",
  'Sigrika': "Solsworn de la Tribu Roya et membre du Fan Club d'Observation des Oiseaux de l'Académie Startorch. DPS Aero sur le terrain qui consomme des cumuls de Rune pour renforcer la Compétence d'Écho et l'Attaque Lourde pour des DGT Aero explosifs avec contrôle de foule.",
  'Rebecca': "Edgerunner et Arsenal de Type Fureur du crossover Cyberpunk: Edgerunners. Hybride Electro qui bascule entre les postures Chasseresse et Cran, conférant un buff de DGT d'Attaque Lourde d'équipe et d'Amplification de tous les DGT via sa tourelle d'Outro.",
  'Lucilla': "Présidente et directrice de l'Académie Startorch, ancienne rédactrice en chef de la principale revue académique de la Nouvelle Fédération. Hybride Glacio à double mode qui confère un buff de DGT de Givre Glaçant ou de DGT de Compétence d'Écho selon le Mode de Résonance, bâtie autour d'un Ultimate à 5 entrées consommant des Photos.",
  'Lucy': "La Netrunner, du crossover Cyberpunk: Edgerunners. DPS Spectro qui accumule TCP/Accès Racine en une Attaque Lourde renforcée et un Ultimate gelant le champ de bataille avec des debuffs de Programme d'Usurpation sélectionnables, infligeant des DGT bonus via le mécanisme de Piratage.",
  'Yangyang: Xuanling': "Gardienne Xuan du Bastion de Xuanfang et sœur de Suisui. DPS Havoc sur le terrain qui alterne les Postures d'Épée Azure et à Plumes, appliquant et consommant Ravage Havoc pour des Dégâts Critiques auto-buffés massifs — l'un des plus hauts plafonds de dégâts du jeu à sa sortie.",
  'Denia': "Étudiante en Néantologie à l'Académie Startorch qui sert secrètement d'agente pour les Fractsidus. Hybride Fusion à double mode qui bascule entre Mise en Scène et Forme d'Effondrement via ses deux Ultimates, jouant soit sur l'archétype d'équipe Explosion Fusion soit sur Tension de Tonalité selon le Mode de Résonance.",
  'Hiyuki': "Miko de Sakura Enflammé d'Ashinohara, désormais dernière membre de la Force de Réaction Spéciale de Lahai-Roi. DPS Glacio sur le terrain qui convertit le Givre Glaçant d'équipe en Morsure Glacio via son Forte, alternant entre Moi Présent et Moi Préfiguré pour un finisseur explosif en Posture Iai.",
  'Suisui': "Directrice de la Guilde du Commerce de Zhaoming et sœur de Yangyang : Xuanling. Soigneuse Glacio à scaling PV qui alterne Posture Zéphyr (soins) et Posture Bruine (DGT Glacio + Givre Glaçant) via sa Compétence de Résonance, culminant en une Amplification de tous les DGT d'équipe via son Outro.",
  'Qingxiao': "Parangon de Mengzhou. DPS Aero sur le terrain qui accumule Cœur du Qin et Cadence de l'Épée via les attaques en Posture Rengainée/Dégainée, puis déchaîne Transcendance Éphémère pour des combos renforcés, proportionnels aux cumuls de Tension de Tonalité - Brouillé et à ses propres cumuls d'Esprit Verrouillé.",
  'Jingran': "Une solitaire s'aventurant dans des profondeurs insaisissables, originaire de Mengzhou. Manieuse de Sabre Fusion à scaling PV qui canalise les postures Vaisseau Yin et Fontaine Yang. DPS Fusion sur le terrain dont l'Attaque Lourde et l'ATQ/DGT sont proportionnels aux PV Max, entrant en état Yinghuo via sa Libération de Résonance pour des frappes de suivi renforcées.",
  'Aalto': "Courtier en informations suave qui se faufile à travers la brume. Sous-DPS Aero qui inflige des DGT Aero hors du terrain via des Attaques Coordonnées déclenchées par son invocation de clone de brume.",
  'Baizhi': "Chercheuse dévouée de l'Académie Huaxu accompagnée de sa compagne You'tan. Soigneuse Glacio qui restaure les PV via sa Compétence de Résonance et sa Libération, offrant un soutien d'équipe constant avec un faible temps de présence sur le terrain.",
  'Chixia': "Patrouilleuse énergique qui traverse Jinzhou en trombe avec ses doubles pistolets. DPS Fusion sur le terrain qui inflige des DGT Fusion via des tirs rapides de Compétence de Résonance et des combos d'Attaque Normale.",
  'Danjin': "Rôdeuse de Minuit qui échange son propre sang contre du pouvoir, traquant voleurs et bandits à travers Huanglong pour se venger. Hybride Havoc qui consomme des PV pour alimenter des Attaques Normales et Lourdes renforcées, gagnant un Bonus de DGT Havoc à mesure que sa santé diminue — utilisée comme buffeuse d'Outro rapide pour un DPS Havoc ou, avec une rotation plus longue, comme DPS principal à part entière.",
  'Yangyang': "Éclaireuse libre des Rôdeurs de Minuit, hybride Efficacité de Concerto/Traction/Régén. de Libération. Sous-DPS Aero qui regroupe les ennemis via sa Compétence de Résonance et sa Libération, accumule jusqu'à 3 cumuls de Mélodie pour une explosion aérienne de Libération de Plumes, et transfère de l'Énergie de Résonance au personnage suivant via son Outro — l'une des rotations les plus rapides et les plus propices au changement rapide du jeu.",
  'Sanhua': "Garde personnelle stoïque de Jinhsi, aussi froide que le givre qu'elle commande. Sous-DPS Glacio à changement rapide qui inflige des DGT Glacio explosifs et amplifie les DGT d'Attaque Normale du personnage suivant via l'Outro.",
  'Taoqi': "Directrice inébranlable de la défense frontalière, à la volonté de fer. Soutien Havoc qui fournit des boucliers via sa Compétence de Résonance et amplifie les DGT de Compétence de Résonance de l'équipe via l'Outro.",
  'Yuanwu': "Vétéran propriétaire de salle de boxe qui combat avec des poings tonitruants. Soutien hybride Electro qui déploie Coin de Tonnerre pour des Attaques Coordonnées hors du terrain et confère à l'équipe une Résistance à l'Interruption (Infusion Électrique) via sa Libération de Résonance.",
  'Mortefi': "Chercheur au tempérament vif dont la musique éclate en crescendos violents. Hybride Fusion qui tire des Attaques Coordonnées Fusion hors du terrain (Rhapsodie Ardente) et confère un buff de DGT d'Attaque Lourde au personnage sur le terrain via l'Outro.",
  'Youhu': "Fantasque évaluatrice d'antiquités qui fait confiance à sa chance en toutes choses. Soutien Glacio qui soigne l'équipe via sa Compétence de Résonance/Forte et confère à l'attaquant en Attaque Coordonnée entrant une massive Amplification de DGT d'Attaque Coordonnée de +100 % via son Outro (Classiques Intemporels) — l'une des plus grandes sources d'amplification de dégâts pour tout type d'attaque dans le jeu.",
  'Lumi': "Navigatrice de Lollo Logistics qui trace des routes à travers des cieux tonitruants. Buffeuse hybride Electro qui alterne les postures de combat à distance Feu Jaune et au corps-à-corps Feu Rouge, infligeant des DGT Electro considérés comme des DGT d'Attaque Normale sur presque tout son kit, et amplifie les DGT de Compétence de Résonance du personnage suivant de 38 % pendant 10 s via son Outro (Escorte) — l'une des seules sources d'Amplification de DGT de Compétence de Résonance du jeu.",
  'Buling': "Consultante des Rives Noires et diseuse de bonne aventure taoïste « Taoïste Chasse-Esprits » qui erre en enquêtant sur l'étrange et le mystérieux, vendant talismans et divination pour financer ses voyages. Soigneuse Electro qui génère des Trigrammes via son Attaque Normale/Compétence/Attaque Aérienne pour débloquer une Libération renforcée qui déploie Électromagnétisme et augmente le Bonus de DGT de Compétence de Résonance d'équipe sur les lancers d'Intro alliés, tandis que son Outro soigne le personnage actif et Amplifie les DGT d'équipe à proximité de 15 % pendant 30 s.",
};

